/* AUTH_UI_START */
const AU={status:null,busy:false,draft:{url:'',title:'',checkpoint:''}};
const auLabels={running:'进行中',queued:'排队',needs_user:'等待本人验证',paused:'已暂停',complete:'完成',canceled:'已取消',failed:'未完成',interrupted:'已中断'};
function auMarkup(s){return `<div class="ac"><b>${s.connected?(s.enabled?'现有授权已开启':'现有授权已暂停'):'原生服务未连接'}</b><p>${s.installed?'Auth Relay 已安装':'尚未安装 Auth Relay'} · ${s.connected?'本机服务已连接':'需要连接服务'}</p><small>范围：${s.scope?.length?s.scope.map(esc).join('、'):'当前没有开启的站点范围'}${s.expiresAt?' · 有效至 '+esc(new Date(s.expiresAt).toLocaleString()):''}</small><p class="lab">同站点验证请求可合并，完成本人验证后从原断点接续。登录成功与业务任务完成分别记录。</p></div><h4>本软件的接力任务</h4><div class="auth-tasks">${s.tasks?.map(t=>`<article class="ac"><b>${esc(t.origin||'站点任务')}</b><p>${esc(auLabels[t.status]||t.status)} · ${esc(t.id.slice(0,8))}</p><div class="row">${t.gateId?`<button data-au-action="focus" data-au-id="${t.id}">前往验证</button><button data-au-action="resume" data-au-id="${t.id}" ${s.enabled?'':'disabled'}>本人已完成，继续</button>`:''}${!['complete','canceled','failed'].includes(t.status)?`<button data-au-action="cancel" data-au-id="${t.id}">取消任务</button>`:''}</div></article>`).join('')||'<p class="lab">还没有由本软件建立的任务。</p>'}</div>${s.otherTaskCount?`<p class="lab">其他软件的 ${s.otherTaskCount} 个任务保留在原生面板，不在这里操作。</p>`:''}<details><summary>为已授权站点建立接力任务</summary><form data-au-form><label>站点地址<input data-au-field="url" type="url" required placeholder="https://…" value="${esc(AU.draft.url)}"></label><label>任务名称<input data-au-field="title" required maxlength="120" value="${esc(AU.draft.title)}"></label><label>原断点 / 下一步<textarea data-au-field="checkpoint" maxlength="2000">${esc(AU.draft.checkpoint)}</textarea></label><button type="submit" ${s.enabled&&!AU.busy?'':'disabled'}>交给现有授权</button></form><p class="lab">范围、开关与有效期由原生面板控制。这里只接入已有授权，不会替你扩大权限。</p></details>`}
refreshAuth=async function(){const el=$('#auth-state');if(!el)return;try{const r=await fetch('/api/studio/auth'),s=await r.json();if(!r.ok)throw new Error(s.error||'读取失败');AU.status=s;if($('#auth-state'))$('#auth-state').innerHTML=auMarkup(s);if(typeof featurePaint==='function')featurePaint()}catch(e){if($('#auth-state'))$('#auth-state').textContent='无法读取授权状态：'+e.message}};
async function auAction(action,args){if(AU.busy)return;AU.busy=true;try{const r=await fetch('/api/studio/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...args})}),d=await r.json();if(!r.ok)throw new Error(d.error||'操作未完成');hint(action==='cancel'?'任务已取消，其他会话保留':'已交给授权服务，继续查看实际任务状态');await refreshAuth()}catch(e){hint(e.message)}finally{AU.busy=false;if($('#auth-state')&&AU.status)$('#auth-state').innerHTML=auMarkup(AU.status)}}
document.addEventListener('input',e=>{if(e.target.dataset.auField)AU.draft[e.target.dataset.auField]=e.target.value});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-au-form]'))return;e.preventDefault();e.stopImmediatePropagation();if(tutorialPractice())return hint('本地练习不建立真实授权任务');void auAction('request',{...AU.draft,clientRequestId:crypto.randomUUID()})},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-au-action]');if(t){e.preventDefault();e.stopImmediatePropagation();if(tutorialPractice())return hint('本地练习不操作真实授权');void auAction(t.dataset.auAction,{taskId:t.dataset.auId})}},true);
/* AUTH_UI_END */
